BEGIN;

CREATE TEMP TABLE tet_sheet (
    scientific_name text PRIMARY KEY,
    common_name text NOT NULL, etymology text NOT NULL, habitat text NOT NULL, identification_character text NOT NULL, leaf_type text NOT NULL, fruit_type text NOT NULL, phenology text NOT NULL, seed_germination text NOT NULL, pest text NOT NULL
) ON COMMIT DROP;

INSERT INTO tet_sheet (scientific_name, common_name, etymology, habitat, identification_character, leaf_type, fruit_type, phenology, seed_germination, pest) VALUES
    ($tet$Aleurites moluccana$tet$, $tet$Ai-Kami$tet$, $tet$Aleurites mai hosi lian Gregu aleuron ho arti "terigu/ikis," ne'ebé refere ba rahun husi ular mutin ne’ebe iha ai tahan, ho moluccana maka significa "hosi rai-Maluku (ilha Maluku, Indonézia)."$tet$, $tet$Baibain hosi tasi ibun to'o foho klaran iha Timor-Leste, ne'e to'o iha ai-laran sekundáriu, tuir mota ho iha dalan foho ne'ebé loke.$tet$, $tet$Ai boot-médiu; nia ai-tahan troka malu, boot, fasil no dala balu 3-lobulu (espesialmente iha nurak nia tahan foun), sorin okos kamutis/silvér; nia tahan kain naruk tebes; nia ai-moruk susar mutin; nia funan mutin iha ramu ne'ebé barak; nia ai-fuan iha kulit parte toos drupe ~4–6 cm, matak bainhira nurak, troka ba kor xokolate-metan bainhira tasak, ho 1–2 ne'ebé iha mina “ai-kami”.$tet$, $tet$Simples$tet$, $tet$Drupe /ai-fuan ne'ebe iha parte toos ida ne'ebe proteje ninia musan$tet$, $tet$Durante tinan tomak$tet$, $tet$Kolleita fuan ne’ebé tuan kór-kafé husi ninia hun ka endokarpu ki'ik ne'ebé maran. 
 Hasai musan liuhosi halo mamar ninia fuan ne’ebé fresku ne’ebé la liu loron barak, loke ninia kulit, fase no hamaran; hasai sira ne’ebé namlele husi bee no rai iha fatin maran ba fulan ~10–12%. Tanba endokarpu mak toos tebes, habai iha loro matan husi loron 2-3 no tuirmai hoban ba bee morna (halo hakfodak termal) atu harahun sira; kuidadu ninia musan husi animal rodente sira. Uza jerminasaun maizumenus médiu 2:1 rai iha leten ba rai henek mota nian, no hakoi musan ne’ebé rahun ona kle’an 2-3cm iha polybag ka iha fatin boot (vazu boot). Ba musan sira ne’ebé hasai ona husi parte toos sei bele too semana ~3-8 (balun iha semana 3-4) no taxa moris bele too 80%, enkuantu ba sira ne’ebé la tau matan di’ak bele too fulan 3-4 no dala balu dodok.$tet$, $tet$Ba kami, perigu kedas durante iha viveirus maka animal sira ne'ebé gosta ba han ai-musan sira ne’ebé iha mina. -proteje fatin jerminasaun no bandeja sira ho rede arame no rede mamar (moskiteiru) no hamoos beibeik rai leten. Iha toos, moras fungus sira kauza ai-fuan naklees no ai-fuan nurak monu, iha tempu ne’ebá iha mós insetu fura ai nia laran, no insetu sira estraga ai nia lolon, no ai nia abut sira. Ai-fuan sira sempre hetan ataka husi lalar no ai musan sira; importante tebes atu hili ai-fuan sira ne’ebé monu no halakon.$tet$),
    ($tet$Tectona grandis$tet$, $tet$Ai-Teka$tet$, $tet$Tectona mai hosi lian Gregu téktōn "karpinteiru/konstrutór", ne'ebé fó hanoin katak uza hanesan ai, no grandis maka lian Latin ba boot/boot.$tet$, $tet$Ida ne’ebé kuda barak liu no dalaruma natural iha foho maran no foho-lolon kalkáriu sira$tet$, $tet$Ai-hun boot ida, ai-hun ne'ebé monu; tahan boot tebes, kontráriu no simples; ninia tahan sira fó mahon iha fulan 3-4 iha parte ikus husi tempu bailoro nian; funan ki’ik (≈8 mm), kór-kafé to'o mutin, iha sanak boot iha parte leten; fuan kabuar, toos, ninia tahan ho kuartu haat, falun iha balaun tetuk ida, taka iha "bexiga", verde-mutin no kór-kafé bainhira sai tasak.$tet$, $tet$Simples$tet$, $tet$Drupe /ai-fuan ne'ebe iha parte toos ida ne'ebe proteje ninia musan$tet$, $tet$Funan: Juñu to'o Setembru; Fuan: Novembru to'o Janeiru$tet$, $tet$Halibur ai-fuan sira ne'ebé tasak no maran; hasai ninia parte sépalu/kálix sira iha li’ur, hafoin eskarifika uitoan ninia kulit ne'ebé toos ho lixa ka fatuk ne'ebé toos. Enxe polybags ho mistura rai no kompos ne'ebé kahur di'ak iha proporsaun 3:1. Kuda fini 3-5 kada saku ho kle’an 1-2 cm ka kuda uluk iha kama jerminasaun nian.$tet$, $tet$Termite (insetu) sira maka problema prinsipál ba ai-teka; sira han iha ai nia laran, halo ai nia laran mamuk no raisin iha ai nia laran - bainhira hetan ataka maka'as, tesi no sunu maka opsaun di’ak liu. Ular oan sira ne'ebé han ai tahan bele hamolik ai-funan lalais; hala’o inspesaun beibeik, mantén ai nia tutun sira nakloke no tesi ninia sanak sira, no hasai ai-funan/sanak sira ne'ebé afetadu maka'as. Ai-lolon sira halo kuak kabuar ki'ik sira no hasai ai rahun sira hanesan pó; evita atu hakanek ai-horis sira no hasai/estraga ai-horis ne'ebé hetan afetadu. Iha viveiru sira no ai-horis sira ne'ebé sei ki'ik, derrepente mate barak depois de mangeira /pipa ne’ebé ladi’ak no halo ai abut aat -Uza fatin mangeira/pipa ne’ebé di’ak, rega bee halo hanesan, no tesi sai ai sanak sira ne’ebé iha sintoma ne’ebé besik atu mate.$tet$),
    ($tet$Toona ciliata$tet$, $tet$Ai-Saria$tet$, $tet$Toona mai hosi naran vernacular indianu "toon/tun" ba ai-hun, no Cilliata maka latinu ba "fringed/hairy", refere ba fulun ki'ik sira iha parte sira hanesan ai-funan nia ninin$tet$, $tet$nia moris iha mota no rai-kuak sira ne'ebé úmidu iha rai-bokur ne'ebé iha drenajen di'ak hosi besik tasi-ibun to'o besik 1,500 m$tet$, $tet$Ai-hun ida ne'ebé aas, ai ne’ebé lalais atu halo tranzisaun, ai lolon ne’ebé sempre forte, kulit li’ur kor malahuk nakukun, kasar; ninia tahan alternadu no pinadu ida ho riska 4-8 ne’ebé kontráriu hosi folletu lancoeladu (ho forma lansa), funan kor roza nabilan; funan ki’ik, mutin no morin, iha parte ikus ne’ebé naruk no junta hamutuk; ai-fuan ho modelu kapsul maran no iha liras 5 ne’ebé bele husik fini ki’ik barak husi leten, fini semo.$tet$, $tet$Kompostu pinnadu (ida de'it)$tet$, $tet$Kapsul$tet$, $tet$Funan: Marsu - Maiu; Fuan: Jullu - Agostu$tet$, $tet$Halibur ai-fuan sira ne'ebé tasak no tasak tomak hosi ai-hun bainhira ai-fuan sira hahú nakfera. Enxe viveiru sira ho mistura rai-leten ne'ebé drenajen di'ak no mós adubu ka rai-henek. Kuda iha rai leten ka taka ho rai rahun uitoan liu no iha liña sira ho distánsia 10 cm;$tet$, $tet$Toon ne’ebé ki’ik (Toona ciliata) dala barak sofre husi ai-sanak ne'ebé hamate husi ai sanak leten no hamosu kro’at /tarak; fiskaliza /cek beibeik pontu sira, mantén lider ida ne'ebé loos, no tesi-no-sunu musan sira ne'ebé afeta ona. Termite (ular oan) sira no besouro powderpost (ular fura ai) sira ataka ai, husik hela kuak ki'ik no ai rahun hanesan trigu no rai rahun- evita kanek, hadook ai hosi rai, no hasai ai nia parte sira ne'ebé afetadu maka'as. Visco parasita mosu hanesan ai-horis verde iha sanak sira; tesi tiha no ai lolon ne'e sei sai di’ak fali kontinua tesi karik mosu fali. Abut no ai laran dodok halo ai-horis sira sai fraku (tahan sira sai kinur, tahan sira ne'ebé nakloke, fungo sira ne'ebé hanesan jamur iha hun); mantén ai nia hun maran no la kanek, no hasai ai-hun sira ne'ebé dodok ona. Proteje ai-oan no ai-oan sira hosi karau ho lutu simples too sira sai di’ak.$tet$),
    ($tet$Sterculia foetida$tet$, $tet$Ai-nitas$tet$, $tet$Sterculia mai hosi lian Latin Sterculius, Ema Romanu nia maromak estrume nian (stercus = estrume), no foetida maka lian Latin ba "iss ladi’ak/fétiku.$tet$, $tet$Ai-hun ida iha rai-tetuk ho rai-tetuk tasi-ibun ne'ebé manas no maran no fatuk-lolon sira, dala barak besik aldeia sira no iha estrada sira nia sorin.$tet$, $tet$Ai-hun ida ne'ebé boot, loos, no tahan fasil monu; kulit ne'ebé kabeer no malahuk; tahan sira nakonu iha ai-sanak nia rohan, tahan sira haree hanesan liman ho liman-fuan 7-9 (iha liman-fuan ho ai-funan 7-9), petíolu naruk (to'o ~20 cm) no ai-funan sira iha morin ne'ebé ladún di'ak; ai-funan iha sanak barak, kór verde to'o kór-roxu ne'ebé mamuk, ho mane no feto iha ai-hun ketak; ai-fuan lubun ida ho folikulu mean ne'ebé mahar ne'ebé sai hanesan ai, ida-idak iha fini oioin ho kór ardózia, oblongu (~1.5–1.8 cm) ho aril mean ki'ik ida.$tet$, $tet$Kompostu palmatu$tet$, $tet$Fuan follicle (fuan ida naruk ne’ebé nakloke husi laran ida hodi fó musan barak)$tet$, $tet$Funan: Fevereiru to'o Marsu, Fuan: Janeiru to'o Fevereiru. Ai-fuan sira tasak besik fulan 11 hafoin ai-funan sira mosu ba dala uluk.$tet$, $tet$Halibur ai-fuan mean ne'ebé tasak ona no fahe ai-fuan sira hodi hasai fini metan sira, hasai fini sira no fase pulpa hotu atu evita fungo. Tau fini sira iha bee laran durante oras 24, hafoin hasai kulit metan ne'ebé mihis ka hamoos uitoan. Kuda iha fatin jerminasaun ho mistura rai-metan no adubu ne'ebé drenajen di'ak iha proporsaun 3:1. Tau fini iha nia sorin ka kuda ida-ne'e atu nune'e nia rohan ne'ebé maka rahun/rahun sai hanesan ka aas liu uitoan hosi rai leten.$tet$, $tet$Iha viveiru sira husi Sterculia foetida, problema prinsipál maka lagarta ne'ebé maka bele kona 70-80% husi ai-oan sira no kauza taxa mate ne'ebé aas tebes. Larva sira suku ai tahan ho seda ne'ebé di'ak, halo kabuar, no han iha ninia laran, husik hela fatin "janela" ne'ebé mihis entre vena sira molok muda ba ai tahan foun. Fiskaliza /cek fatin sira loroloron no hasai ka estraga ai-tahan sira ne'ebé iha ular katar iha laran. Proteje fatin jerminasaun nian ho rede insetu nian ne'ebé di'ak, mantén espasu nosirkulasaun anin nian ho diak, no evita kreximentu ne'ebé buras liu iha area kona loromatan. Iha sinál dahuluk sira, spray biolójiku hanesan spray neem (azadirachtin) bele ajuda hamenus estragu.$tet$),
    ($tet$Albizia lebbeck$tet$, $tet$Ai-Samatuku$tet$, $tet$Albizia fó onra ba Filippo degli Albizzi, ne'ebé maka introdús Albizia ida ba Europa, no lebbeck mai hosi naran lokál Árabe/Índiku "lebbek/labakh$tet$, $tet$Espésie ne'e moris iha estrada ninin ne'ebé foho iha elevasaun ki'ik to'o médiu.$tet$, $tet$Ai-hun ida ne'ebé boot médiu, no tahan fasil monu; kulit malahuk, hanesan nakfera , fulin sira ho pinnadu duplu ho pinnae par 2-4, ida-idak iha fulin ki'ik barak ne'ebé obliku no obliku (~1.5-6.5 × 0.5-3.5 cm); ai-funan sira iha ulun esfériku boot, morin, mamar, kór-mean-verde iha tahan naruk sira; ai-fuan naruk, latan, mihis, ho kulit hanesan surat-tahan, ho kór-kafé ne'ebé mutin, book an iha fini nia leten no la metin.$tet$, $tet$Kompostu pinnadu (Duplu)$tet$, $tet$Pod (fuan naruk ne’ebé iha musan iha laran)$tet$, $tet$Funan: Setembru-Novembru; Fuan: Maiu–Jullu$tet$, $tet$Halibur fuan bainhira sira maran, kor mean tuan, no molok sira nakfera; maran iha loron durante loron balu atu sira loke, depois hamoos no rai musan iha kondisaun maran.
 Halo Pré-tratamentu hodi suli bee manas liu (bee foin tuan) ba musan no hakbesik durante 12–24 oras atu hametin kulit metin.
 Prienxe fatin jerminasaun ho mistura Rai : Rai-rahun : Kompostu ho proporsaun 1:1:1.
 Fila musan to’o kle’an ~1 cm; iha kama, husik musan distánsia ~5 cm malu iha liña sira. Jerminasaun normálmente hahú iha semana 1–2 bainhira uza musan fresku ne’ebé halo ona pré-tratamentu.$tet$, $tet$Iha viveiru sira, ai-oan Albizia dala barak mate tanba moras damping-off no moras apodresimentu abut sira seluk; uza fatin ne’ebé moos no bee bele sai-di’ak (drenajen di’ak), evita rega bee barak liu, no hasai no hamenus moras sira.
 Iha kampu, moras murcha ne’ebé grave bele taka bee dalan iha ai-laran, hodi halo ai-tahan sai kinur, mate derrepente iha sanak sira, no mate sanak balu ka ai tomak. Hasai ai sira ne’ebé afetadu boot no evita kanek ai-abut.$tet$),
    ($tet$Azadirachta indica$tet$, $tet$Sumaer Malae$tet$, $tet$Azadirachta iha orijen husi Persian azad-darakht signifika nune’e ai liberta (nobre ka la sujeitu ba tesi), no indica signifika “husi India.”$tet$, $tet$Espésie ne’e moris iha rai mamuk no baibain kuda besik dalan ninin.$tet$, $tet$Azadirachta indica mak ai hun medida médiu to’o boot, moris halo koroa ronda barak no iha kulit kor malahuk eskuru. Tahan tri-pinnately compound, naruk 20–40 cm. Funan ki’ik, kor mutin to’o kinur-kinur malahuk, morin moris iha sanak. Fuan mak drupe ellipsoidal ida-musan, kor matak–kinur to’o kor uvas bainhira maran. Ai komesa fó fuan bainhira 5 tinan, no bele moris to’o 200 tinan.$tet$, $tet$Kompostu pinnadu (ida de'it)$tet$, $tet$Drupe /ai-fuan ne'ebe iha parte toos ida ne'ebe proteje ninia musan$tet$, $tet$Funan: Janeiru–Marsu; Fuan: Maiu–Agostu$tet$, $tet$Halibur neem nia fuan bainhira sira sai kinur no balu sai mamar, prefere kolleita husi ai hun. Depois husi halo depulp no hamoos, musan tenke rai iha fatin fresku, tanba sira lakon kapasidade rapidamente no la presiza halo skarifikasaun.
 Mistura rai: rai-henek: adubu ho proporsaun 2:1:2 maka média di’ak liu, tau musan 1–2 cm laran iha polybag ka iha fatin boot (raised beds). Jerminasaun normálmente hahú iha loron 4–10 no bele remata iha semana 3–5. Musan fresku iha taxa hahú di’ak liu, enkuantu musan tuan hatudu jerminasaun menus.$tet$, $tet$Ai Neem normálmente rezisténsia, maski hanesan insetu no moras sira iha ne’ebé afeta sira.
 Iha viveiru sira, ai-oan barak sofre husi damping-off (halo husi fungi) no mancha iha tahan husi fungi no bacteria seluk.
 Root rot no pink disease bele dañu ai tuan ka ai boot, halo ramu mate (branch dieback).$tet$),
    ($tet$Acacia mangium$tet$, $tet$Akasia$tet$, $tet$Acacia iha orijen husi Gregu akis (“point/barb”), ne’ebé refere ba ramus/espina iha grupu ida-ne’e, no mangium naran husi naran komún husi Molucca ne’ebé uza ba ai ne’e.$tet$, $tet$Espésie ne’e moris di’ak liu iha rai degradadu no apropriadu ba rehabilitasaun rai, maski barak la moris natural.$tet$, $tet$Ai hun medida médiu–boot ne’ebé moris lalais ho koroa boot; tahan alternadu no boot, tahan metin, kor matak nakukun ho 3–5 veinu paralelu forte; kulit ai kor maron to’o maron forte no ra’as iha ai boot tuun; flores ki’ik, kor kreme–kinur-mean iha kabun naruk ruma ida ne’ebé naruk no kro’at; fuan mak fuan iha pod ida naruk, 7–15 cm, kor matak depois maron-forte/metan, barak hakarak nakfera bainhira maran no loke; musan barak, ki’ik, metin, ki’ik metan, barak ho ponta kinur/laranja ki’ik.$tet$, $tet$Simples$tet$, $tet$Pod (fuan naruk ne’ebé iha musan iha laran)$tet$, $tet$Funan: Julhu–Agostu; Fuan: Dezembru–Fevereiru$tet$, $tet$Halibur ai-fuan Acacia mangium bainhira sira maran tebes, kor mean forte to’o metan, no torse, prefere husik husi ai hun bainhira sira seidauk loke (iha Timor-Leste normálmente iha Outubru–Abril). Fuan bele maran iha loron liu husi habai (sun-dry) hodi fasilita loke no hamoos musan.
 Tanba musan iha kulit metin, halo skarifikasaun antes hodi ba fatin, di’ak liu bainhira tau musan iha bee foin hoban durante ~30 segundu no depois hakbesik iha bee malirin durante 24 oras, ne’ebé bele halo jerminasaun iha 75–90%.
 hakoi musan 0.5–1 cm laran iha média ne’ebé di’ak hodi drenajen (ex.: rai-henek ho adubu) iha polybag ka viveiru. Ho Pré-tratamentu, jerminasaun hahú iha semana 1 no hahú tebes iha semana 2–3; se la halo, jerminasaun moras no la uniform.
 Fornese naroman liu-liu durante 2–4 loron, evita bee sira sai barak (waterlogging), kuda musan ida ba kada polybag, no trasplanta bainhira muda iha 3–4 fulan, bainhira sira sai ~25–40 cm to’o balu.$tet$, $tet$Acacia mangium barak mate tanba heart rot no pink disease, no ai tuan ka ai ne’ebé fraku bele dañu barak tanba insetu ne’ebé mosu rai iha laran ai (wood-boring insects) no cupins, ne’ebé bele halo fraku nia hun sai fraku no kualidade ai menus.
 Heart rot normálmente subar iha ai lolon laran no barak hahú husi ramu tuan ka fitar antigu sira, entaun prevene husi antes tesi aparu.
 Pink disease amostra mancha kinur iha sanak ka hun, halo sanak mate no kada dala balu nakloke; entaun evita husi la kuda ai barak tebes, husik sanak sira iha tempu di’ak hodi anin bele liu, no mantén ai sira moris di’ak ho kuidadu fatin di’ak no kontrola erva danu.
 Ba problema hotu-hotu, hasai no hamoos sanak afetadu, hamoos ho limpa ferramenta, no hasai ai ne’ebé dañu tebes hodi hamenus espalha moras.$tet$),
    ($tet$Alstonia scholaris$tet$, $tet$Ai‑hanek/Rito$tet$, $tet$Alstonia naran omenajen ba botanist Charles Alston, no scholars mak Latin ne’ebé signifika “husi eskola,” referensia ba uza tradisional ai ne’e hodi halo lousa/eskrita (writing slates/blackboards$tet$, $tet$Especie ne’e moris natural iha Timor-Leste hotu-hotu, barak besik kuda iha laran dalan no iha toos laran ne’ebé iha nia tempu.$tet$, $tet$Ai-hun ne’ebé aas tebes ho ai-lolon metin, bainhira poda ka kanek, tahan sai naruk no kabeer; tahan naruk no metin, grupu iha liña 4–8 iha ida fatin iha nia lolon; funan iha sanak nia rohan sira, ki’ik, kor mutin/krem no morin makas; fuan naruk, baluk, hanesan lapis, barak sai iha par, kor matak depois maron bainhira maran, loke hodi fó musan barak; musan barak-liu, musan balun ho fulun, fasil ba anin atu lori.
 Espésie ne’e bele identifika husi tahan 4–8 hanesan liña iha node ida no fuan naruk baluk sira iha par ho musan balu.$tet$, $tet$Simples$tet$, $tet$Fuan follicle (fuan ida naruk ne’ebé nakloke husi laran ida hodi fó musan barak)$tet$, $tet$Funan:May-June; Fuan: Junu-July$tet$, $tet$Ai-fuan Alstonia scholaris mak fuan naruk baluk iha par (paired follicles) ne’ebé suspende iha forma V, no maran bainhira sai husi matak ba mean forte, sai maran no nakfera uitoan, no komesa loke. Iha Timor-Leste, fó fuan normálmente maran iha Juñu–Setembru.
Hodi halibur di’ak, tesi fuan ramu ka ramu follicle antes sira loke no maran iha fuku papél ka polybag malukat, ka liga polibag malukat iha fuan iha ai hodi hela musan bainhira sira loke (dehiscence); evita fuan bokon hodi evita dodok.
Musan ki’ik, espalha husi ka’er ho ai balu, no sira husik kapasidade maran balu, tanba ne’e uza musan fresku no la presiza pré-tratamentu. Kari ai-musan iha rai leten (bed ka tray), la hakoi ai-musan, kari rai-henek balu iha leten. Germinasaun barak hahú iha loron 7–10 no hahú tebes iha loron 2. Mantén rai ai-oan sira iha naroman~50%, bokon balu-liu, kontrola erva danu, no trasplanta iha polybag bainhira muda iha 4–6 semana.$tet$, $tet$Ai-hu'un Alstonia scholaris baibain hetan estragu husi lagarta ne’ebé han du’ut kuandu ai-hun sei foin-sa’e. Tuirmai, ai sira bele hetan estragus husi ular oan ne’ebé halo ai-hun fraku no hamenus kualidade ai-lolon nian.
Hamenus problema sira-ne’e hodi fiskaliza ai-hun beibeik, hasai tiha tahan ka sanak sira ne’ebé moras, hamoos área hale’u ai-hun, no kura ai-hun sira-ne’e hodi fó espasu ne’ebé di’ak no tau matan ho didi’ak. Se ai-hun tesi ona, hamaran no rai ai-lolon sira-ne’e ho loloos, no hasai lalais ai-lolon ne’ebé hetan ona peste atu labele hada’et ba seluk.$tet$),
    ($tet$Calophyllum inophyllum$tet$, $tet$Too/Samplon$tet$, $tet$Calophyllum mai hosi lian Gregu kalos ("furak") + phyllon ("daun"), no inophyllum maka lian Gregu, ne'ebé refere ba ai-hun nia sanak ne'ebé iha nervu/tahan vena.$tet$, $tet$Calophyllum inophyllum moris barak iha area tasi-ibun sira, liu-liu haleu Dili no Baucau.$tet$, $tet$Calophyllum inophyllum maka ai-hun tasi-ibun nian ne'ebé boot-boot, ho ai-lolon ne'ebé loos no metin no koroa ne'ebé namkari no arredondadu; fulin sira simples, mahar no nabilan, oval, ho vena paralelu barak ne'ebé di'ak; ai-funan ki'ik, mutin to'o krem no morin tebes, iha grupu; ai-fuan verde redonda "hanesan nu" ho naruk besik 2-4 cm ne'ebé sai mean-kafé bainhira tasak, ho fini ne'ebé toos iha laran; Espésie ne'e bele identifika hosi fulin oval ne'ebé mahar no nabilan ho vena paralelu barak, ai-funan mutin ne'ebé morin, no ai-fuan verde-to'o-kafé ne'ebé redonda.$tet$, $tet$Simples$tet$, $tet$Drupe /ai-fuan ne'ebe iha parte toos ida ne'ebe proteje ninia musan$tet$, $tet$Funan: Abril-Maiu; Frutasaun: Juñu-Agostu$tet$, $tet$Calophyllum inophyllum nia fuan sira maka drupe redonda (3-5 cm) ne'ebé tasak hosi verde no metin ba kinur-verde/kafé ho isin ne'ebé mamar uitoan, taka fini ida iha fatuk tahan ne'ebé toos. Iha Timor-Leste, halibur ai-fuan sira ne’ebé tasak husi fulan Juñu to’o Agostu, di’ak liu husi ai-hun ka foin monu iha loron hanesan; hamoos ai-fuan sira ne'ebé halibur iha tasi-ibun iha bee-moos hodi hasai masin. Hasai pulp hodi tau iha bee durante kalan tomak, hasai kulit, fase, no maran iha mahon ba tempu badak. Fini sira sei moris lahó pré-tratamentu, maibé kulit sira ne'ebé intaktu hamosu jerminasaun ne'ebé neineik no ladún di'ak durante fulan 2-4. Atu hetan rezultadu ne'ebé lalais liu no uniforme liu, hasai kulit no rahun ho jentil kulit tahan nian hodi rahun, ne'ebé bele hamenus jerminasaun ba semana 3-8 resin. Kuda ho kle’an 1-3 cm iha polybags (ida kada saku) ka iha kama sira ne'ebé espasu, uza mistura ne'ebé drenajen di'ak hanesan adubu:rai-henek:batar kulit (1:1:1) iha mahon ~50% nia okos. Mantein úmidu hanesan, evita bee-sa'e, muda ai-oan sira ba loro-matan iha fulan ~2, no kuda iha fulan 5-6 (aas ~25-30 cm) iha inísiu udan nian.$tet$, $tet$Calophyllum inophyllum normálmente maka ai-hun tasi-ibun ne'ebé toos, maibé ai-horis joven sira no ai-horis sira ne'ebé fó fuan bele lakon nafatin área fulin nian no fó ai-fuan/mina menus se peste sira mosu. Mineiru sira halo liña mihis ka "túnel" ne'ebé ladún di'ak iha ai-horis nia laran no bele kauza ai-funan monu sedu iha ai-horis ki'ik sira; kontrola sira liuhosi verifikasaun regulár, hasai no estraga ai-tahan sira ne'ebé maka aat sedu, mantén ai-oan sira saudavel ho mahon, bee no adubu, no uza spray ho baze neem iha viveiru sira bainhira presiza. Insetu eskala sira haree hanesan bubu ki'ik sira iha ai-sanak sira no iha ai-tahan nia okos no halo ai-tahan sira sai kole; hamenus sira hodi tesi no estraga ai-sanak sira ne'ebé hetan infestasaun maka'as, fase/hamoos insetu sira hosi ai-sanak sira ho bee moos (ka sabaun/bee ahu-ruin ne'ebé kmaan), no rega neem iha ai-sanak sira nia okos no ai-sanak sira ne'ebé mamar.$tet$),
    ($tet$Falcataria falcata$tet$, $tet$Ai‑bahe/Ai-Kafe$tet$, $tet$Falcataria refere ba "falcate" (ho forma hanesan ai-sanak), ne'ebé deskreve forma ai-horis nian, no falcata maka lian Latin ba "ho forma ai-tahan/kurva hanesan ai-sanak", refere fali ba ai-horis nia tahan sira$tet$, $tet$Falcataria falcata moris di’ak liu iha área rai-tetuk ne’ebé malirin liu iha Timor-Leste (hanesan Dare, Aileu, no Ermera) no baibain kuda nu’udar ai-horis mahon ba kafé.$tet$, $tet$Falcataria falcata maka ai-hun ida ne'ebé buras lalais tebes ho médiu-boot, dala barak aas 24-30 m (bele aas liu), ho lolon ne'ebé loos no tahan ne'ebé naruk no klaru; koroa iha área nakloke sira haree hanesan sombriña; fulin sira kompostu, ho fulun, ho ai-funan ki'ik barak ne'ebé maka kurva uitoan, no ai-funan sira iha par barak; ai-funan sira mutin no ki'ik, hanesan sinál ki'ik sira; ai-fuan ida ne'ebé ki'ik no latan ho naruk 10-13 cm no luan ~2 cm, sai kór-kafé bainhira maran no nakloke; fini 15-20 iha fuan pod ida, ki'ik (~6 mm), nakukun; Espésie ne'e bele identifika hosi ai-lolon ne'ebé aas no loos ho koroa hanesan sombriña, fulin ho fulun barak ne'ebé kurva ki'ik, no fuan pod latan ne'ebé ki'ik.$tet$, $tet$Kompostu pinnadu (Duplu)$tet$, $tet$Pod (fuan naruk ne’ebé iha musan iha laran)$tet$, $tet$Funan: Marsu to'o Juñu & Outubru to'o Dezembru; Frutasaun: Maiu to'o Agostu & Dezembru to'o Fevereiru$tet$, $tet$Falcataria falcata produz pod ne'ebé mihis no latan iha grupu ne'ebé namlele ne'ebé nakfila hosi kór verde ba kór-kafé pálidu/nakukun uniforme, sai maran no hanesan surat-tahan; vagem ne'ebé maduru hasai fini ki'ik barak ne'ebé latan. Halibur pod sira antes sira fahe naturalmente, di'ak liu hosi ai-hun. Iha Timor-Leste, vagem maduru tipikamente disponivel Maiu–Agostu no fali Dezembru–Fevereiru. Maran iha loro-matan ba tempu badak to'o sira nakloke, hafoin hasai fini sira, maran iha mahon, no rai iha kontentór malirin ne'ebé taka metin. Fini sira iha dormansia ho falun metin, nune'e halo pré-tratamentu hodi fakar bee-manas ba fini sira no hasai bainhira bee sai malirin durante oras 12-24. Kuda ho kle’an 0.5-1 cm iha rai-henek ka saku sira (2-3 kada saku, mihis depois) uza mistura rai-leten: ai-uut (1:1). Ho tratamentu, jerminasaun lalais tebes (dala barak 80%+ iha semana ida nia laran, dala ruma iha loron 1-2 nia laran); fó mahon ne'ebé kmaan de'it iha jerminasaun no muda ba loro-matan tomak iha semana 1-2 nia laran, rega beibeik maibé evita bee-sa'e.$tet$, $tet$Falcataria falcata (sengon/falcata) moris lalais, maibé bele hetan infesaun husi gall rust no stem borers, liuliu iha kuda tipu ai ida de'it ne'ebé maka'as, ida-ne'e bele halo kreximentu sai neineik no bele mós hamate ai-horis ki’ik sira. Ferrujen iha gal kauza "bubu" kór-kafé, nakfera iha sanak sira no sanak sira, dobrada no kreximentu ne'ebé buras, no dala ruma sanak sira maran; hamenus ida-ne'e hodi evita bloku sira ne'ebé nakonu (kahur ho ai-horis/ai-horis sira seluk), kuda de'it ai-oan ne'ebé moos no saudavel, tesi no estraga ai-sanak sira ne'ebé iha moras sedu, no hasai ai-horis sira ne'ebé infetadu maka'as. Atake husi stem borer hatudu hanesan kuak ki'ik sira ho serru pó no sanak sira ne'ebé mate iha kuak nia leten; jere ida-ne'e liuhosi espasu ne'ebé di'ak, verifikasaun regulár, oho grub iha kuak laran ho arame no taka kuak ho rai-mean + karau-ten, no hasai ai-hun sira ne'ebé hetan ataka maka'as no estraga ai-hun sira ne'ebé hetan infestasaun.$tet$),
    ($tet$Canarium vulgare$tet$, $tet$Ai-Kiar$tet$, $tet$Canarium mai hosi vernakular malaiu/moluku kanari/kenari, no vulgare maka lian Latin ba "komún/baibain", karik refere ba nia akontesimentu gregáriu iha habitat$tet$, $tet$Canarium vulgare moris dalaruma iha mota foho nia sorin, liuliu haleu Baguia no Liquica.$tet$, $tet$Ai-hun ida ne'ebé aas to'o besik 45 m ho abut ne'ebé iha manteiga; ai-tahan sira maka kompostu, normálmente ho ai-funan oval 9-11; ai-funan sira ki'ik no ketak hanesan mane no feto, moris iha grupu iha sanak nia rohan; ai-fuan iha isin, oval no mos, verde bainhira sei ki'ik no sai kór-roxa nakukun ba metan bainhira tasak; iha ai-fuan nia laran iha fatuk toos ida ho musan laran ne'ebé bele han; Espésie sira bele identifika hosi ai-funan 9-11 no ai-fuan oval ne'ebé maka sai kór-roxu/metan nakukun ho musan ne'ebé bele han iha laran.$tet$, $tet$Kompostu pinnadu (ida de'it)$tet$, $tet$Drupe /ai-fuan ne'ebe iha parte toos ida ne'ebe proteje ninia musan$tet$, $tet$Funan: Setembru to'o Dezembru; Frutasaun: Maiu to'o Jullu$tet$, $tet$Canarium vulgare produz drupes ne'ebé mos, ovoide ne'ebé tasak husi kór verde ba kór-roxu/metan nakukun, ho isin ne'ebé kmaan no fatuk ne'ebé toos tebes ne'ebé taka nia musan ne'ebé iha mina. Halibur ai-fuan sira ne'ebé tasak ona husi fulan-Maiu to'o Jullu bainhira metan no toos ona, di'ak liu hili husi ai-hun ka halibur beibeik husi rai, soe ai-fuan sira ne'ebé hetan estragu husi insetu ka iha dodok. Hasai no hamaran sira iha loro-matan; fuan maran sira bele rai durante fulan barak (dala barak to'o ~1.5 tinan) ho lakon viabilidade uitoan. Tanba endokarpu ne'ebé toos atraza jerminasaun, halo pré-tratamentu hodi rega fatuk sira durante loron 2, hafoin rahun ho jentil ka tesi/arkivu rohan ida atu husik bee tama. Kuda ho kle’an 3-5 cm iha meiu ne'ebé iha drenajen di'ak (rai-henek: rai: kompos 1:1:1), ideálmente horizontalmente ka ho sorin ne'ebé rahun uitoan ba kraik, iha sombra ~50% nia okos. Mantein úmidu beibeik maibé ho drenajen di'ak. Ho harahun, jerminasaun bele hahú iha semana 6-8 no kontinua durante fulan 2-3, enkuantu fuan sira ne'ebé la hetan tratamentu bele lori fulan 6-12. Mantein mahon no fluxu anin nian, hafoin neineik-neineik hasai ba naroman ne'ebé aas liu; transplantasaun iha fulan 6-9 (besik 20-30 cm aas) iha inísiu udan nian.$tet$, $tet$Canarium vulgare normálmente tahan, maibé ai-horis ki’ik sira, musan sira no ai-fuan sira bele hetan estragu nafatin no fó kreximentu ne'ebé neineik liu ka produsaun ne'ebé ki'ik liu. Termite /ular sira bele halo kuak baze, no kauza mohu derrepente; hamenus ida-ne'e hodi uza ai-oan ne'ebé forte, hamoos ai-tahan tuan/lixu ai-tahan, hadook mulsa hosi ai-horis, no uza adubu ho di'ak. Insetu ne'ebé han musan bele halo metan musan nia ponta no estraga ai-funan/ai-fuan sira; jere ho espasu ne'ebé di'ak, tesi no estraga musan sira ne'ebé hetan estragu, verifikasaun beibeik, hili ho liman sedu, no rai ai-horis sira ne'ebé iha ai-funan besik ba insetu sira ne'ebé ajuda.$tet$),
    ($tet$Casuarina equisetifolia$tet$, $tet$Ai-Kakeu$tet$, $tet$Casuarina mai hosi liafuan malaiu kasuari (kasoariu), refere ba ai-hun nia sanak sira ne'ebé hanesan ai-sanak ne'ebé hanesan manu-fuik nia fulun, no equisetifolia maka lian Latin ba "horsetail-leaved", ne'ebé deskreve nia fulin sira ne'ebé mihis no iha artikulasaun hanesan ho Equisetum (ai-horis horsetail).$tet$, $tet$Casuarina equisetifolia moris barak iha Timor-Leste laran tomak, mosu naturalmente tuir area tasi-ibun, no mos moris diak iha tipu rai oi-oin.$tet$, $tet$Ai-hun ida ne'ebé boot-médiu dalabarak aas 10-30 m; Tahan sira haree hanesan daun kor matak ne'ebé mihis hanesan ameasa; kulit kor malahuk-xokolate no áspera; funan sira ki'ik tebes no ladún hatudu, ai-funan mane iha korat mihis no ai-funan feto hanesan musan ki'ik; ai-fuan haree hanesan kóniku ki'ik ida, verde depois kór-kafé, loke bainhira maran; fini sira ki'ik tebes no latan ho liras ne'ebé mihis hanesan surat-tahan, lori hosi anin; Espésie sira bele identifika hosi sanak sira ne'ebé hanesan ai-sanak verde no ai-fuan ki'ik sira hanesan kóniku.$tet$, $tet$Simples$tet$, $tet$Kapsul$tet$, $tet$Funan: Setembru to'o Outubru; Frutasaun: Fevereiru to'o Juñu.$tet$, $tet$Casuarina equisetifolia produz ai-fuan ki'ik, hanesan kóniku ai-tahan ne'ebé sai maduru hosi kór verde ba kór-kafé ka kafe no sai maran no fraku bainhira sira tasak. Kóniku sira ne'ebé maduru loke naturalmente hodi hasai fini ki'ik, ho liras no di'ak liu atu halibur bainhira sira hasai ho fasil ka monu hafoin anin, normalmente entre Fevereiru-Marsu no dala ruma fali iha Juñu-Jullu. Kóniku sira ne'ebé halibur ona tenke maran iha loro-matan durante loron balun to'o eskala sira nakloke no fini sira sai. La presiza tratamentu antes. Kuda fini sira iha fatin ne'ebé kle’an (besik 0.5-1 cm) iha meiu ne'ebé iha drenajen di'ak hanesan rai-henek ka mistura rai-henek-rai, taka uitoan no taka ho mulsa atu prevene fase. Jerminasaun hahú iha loron 5-10 nia laran no barak liu kompletu iha semana 2-3 nia laran. Mantein kama sira úmidu maibé labele nakonu ho bee, no mantén loro-matan tomak. Hasai ai-oan sira iha semana 3-4 ba iha polybag, no transplanta ba to'os iha fulan 3-4 bainhira aas 15-20 cm.$tet$, $tet$Peste prinsipál maka lagarta ne'ebé han ai ne'ebé halo kuak no túnel sira iha ai-tahan no sanak sira, ne'ebé bele hafraku ai-hun. Métodu simples ida ne'ebé la'ós kímiku maka kontrolu mekániku, buka túnel nakloke nian no taka ho material hanesan alkatraun/lisa atu nune'e larva labele kontinua. Infestasaun dala barak sa'e hafoin udan-been no normálmente kondisaun manas liu, maran liu kuda iha fatin ne’ebé adekuadu no sai alerta liután hafoin periodu udan ajuda hamenus estragu. Casuarina /ai-kakeu mós bele hetan mealybugs (insetu ki'ik, mutin, hanesan koto) ne'ebé tuur iha ai-sanak no ai-sanak sira no xupa ai-horis nia been. Dala barak sira husik hela kamada ida ne'ebé belit, ne'ebé depois bele nakfila ba fungo metan, no ai-hun ne'e bele haree fraku, mean no moris neineik. Kontrola ida-ne'e hodi fase/hamoos sira iha ai-hun ki'ik sira, tesi no estraga ai-sanak sira ne'ebé hetan infestasaun maka'as, no rega mina neem/mistura bazeia ba neem iha parte sira ne'ebé afetadu; mós mantén fatin ne’e moos no hamenus lalar, tanba lalatak proteje peste hirak ne’e.$tet$),
    ($tet$Pterocarpus indicus$tet$, $tet$Ai-na$tet$, $tet$Pterocarpus mai hosi lian Gregu pteron ("ala") + karpos ("ai-fuan"), ne'ebé refere ba nia fini ho liras, no indicus maka lian Latin ba "Índia/Índia", ne'ebé hatudu ba nia asosiasaun ho rejiaun Índia iha naran botániku uluk.$tet$, $tet$Pterocarpus indicus moris iha estrada ninin foho-lolon no komún iha Timor-Leste laran tomak.$tet$, $tet$Ai-hun ida ne'ebé sempre matak to'o semi-deciduous ho médiu-boot to'o besik 40 m, koroa ida ne'ebé namkari ho forma kúpula no sanak sira ne'ebé monu, kulit ne'ebé rahun uitoan no iha eskala; bainhira tesi nia bele suli bee-mean; fulin sira alterna no kompostu, ai-funan sira iha sanak sira ne'ebé iha ai-sanak nia hun no sanak sira ne'ebé namkari, besik, mean, nabilan, 15." cm; ai-fuan ida ne'ebé hanesan disko ne'ebé latan ho liras ne'ebé luan hale'u nia ninin, kór matak no fulun uitoan bainhira sei ki'ik, sai kór-kafé pálidu no mos bainhira tasak, no nia la nakloke fini 1–2 kada vazu, kór-kafe; Ai-hun ida ho medida médiu ne'ebé monu to'o semi-verde, ho koroa ne'ebé luan tebes hanesan sombriña no sombra ne'ebé maka'as, nia tahan dala barak badak ho sanak sira ne'ebé namkari ki'ik, kulit kór-malahuk no mos to'o rahun uitoan; Daun boot, ho fulun, hanesan samake nia fulin kompostu duplu ne'ebé halo hosi ai-funan ki'ik barak; Ai-funan boot, furak tebes, mean nabilan to'o laranja-mean, dala barak ho pétala ida ne'ebé marka ho kór mean/mutin; Ai-fuan naruk, latan, ai-tahan toos ne'ebé namlele tun, sai kór-kafé nakukun bainhira tasak, normálmente naruk 30-60 cm; Musan toos, musan kór-kafé oval ne'ebé arranja iha liña ida iha vagem laran; Espésie ne'e bele identifika hosi nia fulin sira ne'ebé hanesan samake, ai-funan mean-laranja nabilan, no ai-tahan ne'ebé naruk.$tet$, $tet$Kompostu pinnadu (ida de'it)$tet$, $tet$Pod (fuan naruk ne’ebé iha musan iha laran)$tet$, $tet$Funan: Agostu to'o Setembru; Frutasaun-Maiu to'o Juñu$tet$, $tet$Pterocarpus indicus produz vagem ne'ebé maka redonda, ho liras (luan 4-6 cm) ne'ebé maka nakfilak hosi verde ba kór-kafé bainhira sira sai maduru, sai maran no hanesan surat-tahan ho fini sentrál ne'ebé maka metin. Iha Timor-Leste, vagem normalmente rekolla durante tempu maran (maizumenus Juñu–Jullu) bainhira sira sai kór-kafé tomak no metin, di’ak liu molok sira monu. Vagem sira la nakloke, nune'e fini sira taka metin nafatin; tesi ka tesi parsialmente liras ajuda hadi'a kontaktu rai no absorsaun umidade. Kuda ai-horis tomak iha rai-leten, hodi hanehan sira ho kmaan iha rai-henek ka rai-henek ne'ebé iha drenajen di'ak no taka ho kmaan tebes. Mantein kama ne'e úmidu maibé labele nakonu ho bee. Jerminasaun normalmente hahú iha loron 3-4 nia laran iha kondisaun manas. Fó mahon ne'ebé kmaan no anin ne'ebé di'ak, no hamoos du'ut beibeik. Bainhira ai-oan sira dezenvolve ona fulin loloos oioin, transplanta ba iha polybag no sai toos neineik molok kuda iha to'os ho aas 15-20 cm.$tet$, $tet$Pterocarpus indicus bele hetan afetadu maka'as hosi moras mohu, iha ne'ebé ai-funan sira sai mean, sanak sira maran fali, no ai-horis tomak bele mate, no ida-ne'e mós bele hetan mineiru ai-funan sira no ai-tahan sira ne'ebé halo ai-funan sira sai deformadu ka hafraku ai-tahan. Estratéjia di’ak mak kuda de’it ai-oan ne’ebé saudavel, mantén espasu ne’ebé di’ak no kuda kahur, no evita estraga ai-kulit durante hamoos du’ut ka tesi.$tet$),
    ($tet$Delonix regia$tet$, $tet$Ai‑kesi/Madre‑Kakau/Samatuku Malae$tet$, $tet$Delonix mai hosi lian Gregu delos ("klaru/vizivel") + onyx ("kukun"), refere ba nia pétala sira ne'ebé maka furak, hanesan kukun, no regia maka lian Latin ba "liurai", ne'ebé deskreve nia ai-funan sira ne'ebé maka furak no nabilan.$tet$, $tet$Delonix regia baibain kuda iha estrada ninin no ema barak haree iha nasaun tomak.$tet$, $tet$Ai-hun ida ho medida médiu ne'ebé monu to'o semi-verde, ho koroa ne'ebé luan tebes hanesan sombriña no sombra ne'ebé maka'as, nia tahan dala barak badak ho sanak sira ne'ebé namkari ki'ik, kulit kór-malahuk no mos to'o rahun uitoan; Daun boot, ho fulun, hanesan samake nia fulin kompostu duplu ne'ebé halo hosi ai-funan ki'ik barak; Ai-funan boot, furak tebes, mean nabilan to'o laranja-mean, dala barak ho pétala ida ne'ebé marka ho kór mean/mutin; Ai-fuan naruk, latan, ai-tahan toos ne'ebé namlele tun, sai kór-kafé nakukun bainhira tasak, normálmente naruk 30-60 cm; Musan toos, musan kór-kafé oval ne'ebé arranja iha liña ida iha vagem laran; Espésie ne'e bele identifika hosi nia fulin sira ne'ebé hanesan samake, ai-funan mean-laranja nabilan, no ai-tahan ne'ebé naruk.$tet$, $tet$Kompostu pinnadu (Duplu)$tet$, $tet$Pod (fuan naruk ne’ebé iha musan iha laran)$tet$, $tet$Funan: Abril to'o Maiu; Frutasaun: Outubru to'o Dezembru$tet$, $tet$Delonix regia produz pod naruk, pod ai (30-60 cm) ne'ebé sai kór-kafé nakukun no toos bainhira tasak, normalmente hosi fulan-Maiu to'o fulan-Jullu. Ai-horis ne'ebé maduru tenke halibur diretamente hosi ai-hun bainhira maran hotu ona, hafoin maran liután iha loro-matan no fahe hodi hasai fini ne'ebé latan no toos. Fini sira iha fulun ne'ebé maka metin tebes, nune'e eskarifikasaun maka esensiál—karik hodi taka fulun fini nian ka rega iha bee manas to'o book an. Kuda fini scarified ho kle’an 0.5-1 cm iha rai-henek ka rai-henek-loam, ho espasu ne'ebé kmaan se iha fatin jerminasaun. Jerminasaun lalais bainhira hetan tratamentu, ho abut sira ne'ebé mosu iha loron 4-7 no fini barak liu moris iha semana rua nia laran. Fó mahon ne'ebé kmaan iha inísiu no halo rai sai úmidu maibé ho drenajen di'ak. Ai-oan sira moris lalais no bele transplanta iha semana 3-4 bainhira aas besik 10-15 cm, neineik-neineik halo sira sai toos ba loro-matan tomak.$tet$, $tet$Espésie ne’e dala barak hetan infesaun ho abut dodok, liuliu iha fatin sira ho udan boot, ne’ebé neineik estraga abut no halo fraku ai-horis tomak. Ida-ne'e mós hetan ataka hosi bezouru ki'ik sira no sira nia oan sira, ne'ebé fura iha fini-fatin sira no halo kuak sira atu nune'e fini sira fakar sai. Dala ruma insetu sira ne'ebé halo musan sai estraga kreximentu foun ne'ebé mamar, hodi hamenus sanak ne'ebé saudavel. Iha kazu balun, lalar/insetu sira ne'ebé han ai-funan bele hasai ai-funan barak liu ka hotu.$tet$),
    ($tet$Tamarindus indica$tet$, $tet$Ai‑sukaer$tet$, $tet$Tamarindus mai hosi fraze árabe tamr e hind ne'ebé signifika "data indianu", refere ba nia pulpa hanesan data, no indicus maka lian Latin ba "husi Índia/indianu", ne'ebé hatudu ba nia asosiasaun naruk ho Índia iha naran uluk.$tet$, $tet$Tamarindus indica maka komún no barak, liuliu iha aldeia sira nia sorin.$tet$, $tet$Ai-hun ida ne'ebé moris naruk ho ai-horis ne'ebé sempre matak to'o semi-deciduous médiu-boot, ho tahan ne'ebé mahar no koroa ne'ebé luan, redonda, no namkari ne'ebé fó mahon ne'ebé kle’an; Tahan ki'ik, ne'ebé haree kmaan ho fulin kompostu ida de'it ho par barak hosi ai-funan ki'ik sira, ne'ebé fó aparénsia fulun ne'ebé di'ak; Ai-funan ki'ik, iha grupu badak, mean-mutin to'o kreme ho liña mean/laranja ne'ebé di'ak, ladún hatudu; Ai-fuan ne'ebé mahar, kurva to'o kór-kafé ne'ebé loos, maran no fraku uitoan bainhira tasak, ho pulpal midar-siin ne'ebé isin iha laran; musan sira ne'ebé toos, mós, musan kór-kafé nakukun ne'ebé nabilan ne'ebé tau iha pulpa nia laran; Espésie ne'e bele identifika hosi nia koroa ne'ebé maka'as, nia fulin ne'ebé di'ak, no nia kulit kór-kafé ho pulpa ne'ebé bele han isin ne'ebé midar-siin.$tet$, $tet$Kompostu pinnadu (ida de'it)$tet$, $tet$Pod (fuan naruk ne’ebé iha musan iha laran)$tet$, $tet$Funan: Juñu to'o Jullu; Frutasaun: Marsu Abril$tet$, $tet$Tamarindus indica produz pod ne'ebé naruk no frajil ne'ebé sai kór-kafé no maran bainhira tasak, hodi taka fini ne'ebé toos no nabilan iha pulpa ne'ebé belit. Iha Timor-Leste, ai-fuan sira normalmente tasak iha fulan Juñu to’o Setembru no di’ak liu halibur diretamente husi ai-horis bainhira sai kinur tomak atu evita estragu husi insetu ka umidade. Depois de rekolla, hasai ninia isin, hamoos fini sira, no maran iha mahon molok rai. Fini sukaer iha kulit ne'ebé toos no presiza tratamentu antes atu bele moris ho di'ak; rega iha bee manas (besik 80 °C) no husik atu malirin durante oras 12-24, ka tesi uitoan fini nia kulit, hadi'a tebes rezultadu sira. Kuda fini sira ho kle’an besik 1 cm iha rai-henek ka rai-henek ne'ebé drenajen di'ak, tantu iha polybag ka iha viveiru. Jerminasaun normalmente hahú iha loron 5-10 nia laran no barak liu kompletu iha semana 2-3 nia laran. Fó mahon ne'ebé kmaan iha inísiu, hafoin neineik-neineik fó ai-oan sira ba loro-matan tomak. Ai-oan moris lalais no prontu atu transplanta bainhira iha idade fulan 3 resin.$tet$, $tet$Ai-tamarindu bele hetan afetadu maka'as hosi insetu ki'ik sira ne'ebé xupa been (hanesan eskala no mealybugs) no hosi insetu sira ne'ebé buras iha vagem /pod, fini, ka sanak sira, ne'ebé bele hamenus kuantidade ai-fuan di'ak ne'ebé ita bele fa'an. Fatin oioin relata problema oioin—área balu haree bezouru sira ne'ebé han vagem, termite sira, ka peste sira ne'ebé ataka tamarindu ne'ebé rai hela hafoin kolleita. Iha tempu balu, ai-fuan sira ne'ebé maka bele sai kestaun boot no hamenus maka'as produsaun ne'ebé maka bele fa'an. Tamarindu mós bele hasoru moras ai-horis nian oioin ne'ebé mosu hanesan marka iha fulin ka pó mutin iha fulin sira, revestimentu metan ne'ebé iha mofo, no ai-tahan, abut, ai, ka kulit ne'ebé dodok ka estraga.$tet$),
    ($tet$Eucalyptus urophylla$tet$, $tet$Ai‑ru$tet$, $tet$Eucalyptus mai hosi gregu eu ("posu") + kalyptos ("taka"), refere ba ai-funan nia musan ne'ebé taka, no urophylla mai hosi gregu oura ("ikun") + phyllon ("tahan"), signifika "tahan-ikun", deskreve nia forma tahan.$tet$, $tet$Eucalyptus urophylla dalaruma hetan iha altitude aas estrada ninin no foho sira, liuliu haleu Dare, Aileu, Ermera, no Baguia.$tet$, $tet$Ai-hun aas ida ne'ebé sempre matak ne'ebé bele moris besik 45-55 m, normálmente ho ai-hun ne'ebé loos; kulit normálmente persistente, no mós fibrozu uitoan, kór-kafé-mean to'o kór-kafé ho ransu sira ne'ebé ladún kle’an, dala ruma aspera liu besik baze; tahan nurak barak liu iha par opostu, luan no ho forma lansa; tahan tuan naruk, ho forma lansa-ki'ik, ne'ebé kaer alternadu ba besik-opostu; Ai-funan ki'ik, iha grupu ki'ik sira hosi ai-funan nia hun; Ai-fuan ki'ik, ai-maran kapsul, ho forma kopu to'o hanesan kóniku; Musan ki'ik tebes, metan, no kurva uitoan/forma fulan-mean; Eucalyptus urophylla bele identifika hosi E. alba hosi nia jerálmente aas liu, toman ne'ebé loos liu, nia akontesimentu baibain iha altitude besik 500 m, no nia kulit mean-kafé (dala barak ho fissural sira ne'ebé ladún kle'an) envezde kulit mutin/kreme ne'ebé mós hosi E alba.$tet$, $tet$Simples$tet$, $tet$Kapsul$tet$, $tet$Funan: Dezembru to'o Janeiru; Frutasaun: Abril to'o Maiu;$tet$, $tet$Eucalyptus urphylls produz fini ki'ik, ne'ebé maka iha kapsula ne'ebé maka sai bainhira kapsula maduru maran no nakloke. Fini sira halibur hosi kapsula sira ne'ebé dezenvolve ona, maran, no hamoos molok rai ka kuda. Atu hadi'a jerminasaun, fini sira hetan benefísiu hosi estratifikasaun malirin hodi mantén sira úmidu no iha jeleira durante semana 4-6, ne'ebé ajuda hakotu dormansia fiziolójika. Hafoin tratamentu, fini sira kuda iha superfísie iha meiu ne'ebé di'ak, ho drenajen di'ak hanesan rai no rai-henek, no prienxe uitoan lahó taka. Jerminasaun akontese di'ak liu iha 20-25 °C iha naroman ne'ebé kmaan no ventilasaun di'ak, normalmente iha semana 2-3 nia laran. Ai-oan sira transplanta ba iha polybags hafoin loron 30 bainhira sira dezenvolve ona fulin loloos 2-4. Ai-horis joven sira prefere loro-matan nakonu no rai ne'ebé iha drenajen di'ak, rai ne'ebé ásidu uitoan. Ho kuidadu di'ak, Eucalyptus moris lalais, dala barak atinje metru balun iha tinan dahuluk nia laran$tet$, $tet$Amblypelta no Amorbus maka peste hanesan insetu ne'ebé estraga eukaliptu hodi sona ai-horis nia sanak sira no hemu ai-horis nia been. Iha ai-horis sira ne'ebé sei ki'ik tebes, ida-ne'e bele halo ai-horis nia tutun sira namlaik no mate fali, dala ruma hamate ai-horis nia sanak prinsipál no husik ai-hun ne'e sai hanesan ai-horis ka ai-riin. Opsaun kontrolu naturál sira seidauk estuda ho di'ak, maibé dala ruma sujere atu kuda ai-horis sira seluk hamutuk (interkultivasaun).$tet$),
    ($tet$Eucalyptus alba$tet$, $tet$Ai‑bubur$tet$, $tet$Eucalyptus mai hosi lian Gregu eu ("di’ak") + kalyptos ("taka"), ne'ebé refere ba ai-horis nia tutun, no alba maka lian Latin ba "mutin", ne'ebé refere ba ai-hun nia kulit ne'ebé mutin/mutin.$tet$, $tet$Eucalyptus alba moris barak iha foho tasi-ibun ho altitude ki’ik liu-liu tuir korredór Dili–Baucau.$tet$, $tet$Ai-hun ki'ik to'o médiu ida ne'ebé baibain aas besik 5-18 m, ho koroa ne'ebé namkari besik 5-15 m luan, ai-hun dala barak dobrada; kulit ne'ebé mós, hanesan pó, no kór-roza-mean to'o mutin ka kór-kreme, dala barak haree pálidu hosi dook; Daun sira iha ai-horis joven sira troka malu, luan no ho forma hanesan manu-tolun to'o kuaze redonda, boot loos; ai-funan adultu ho forma ovo to'o forma lansa, ki'ik liu duké ai-funan juvenil; Ai-funan sira moris iha grupu hitu iha ai-tahan badak, ai-funan sira mutin; Ai-fuan ki'ik, kapsula ai-tahan, ho forma kóniku to'o metade redonda; Fini ki'ik no típiku husi ai-eukaliptu; Espésie ne'e bele identifika hosi nia aas ne'ebé badak liu, nia tahan ne'ebé dobrada, no nia kulit mutin/kreme ho ai-funan mutin sira$tet$, $tet$Simples$tet$, $tet$Kapsul$tet$, $tet$Funan: Dezembru to'o Janeiru; Frutasaun: Abril to'o Maiu;$tet$, $tet$Eucalyptus alba produz fini ki'ik tebes, hanesan rai-rahun ne'ebé taka iha kápsul ai ki'ik sira ne'ebé dezenvolve iha grupu sira tuir sanak sira. Nu'udar kapsula sira sai tasak, sira muda hosi kór verde ba kór kafé no sai maran no metin. Kolesaun fini tenke halo diretamente hosi ai-hun antes kapsula sira nakloke naturalmente, tanba bainhira sira loke fini sira ne'ebé di'ak lakon ho fasil. Kapsula sira ne'ebé halibur ona bele maran iha loro-matan iha bandeja ka kaixa ida durante loron balun to'o sira hasai fini sira, ne'ebé hafoin bele hamoos no rai maran. Ba jerminasaun, la presiza pré-tratamentu. Fini sira tenke espalla ho kmaan iha superfísie meiu ne'ebé di'ak, ho drenajen di'ak hanesan rai-henek ka mistura rai-henek rai no prenxe ho kmaan lahó taka. Mantein umidade ne'ebé kmaan no fluxu anin ne'ebé di'ak. Jerminasaun normalmente hahú iha loron 7-14 nia laran iha kondisaun manas.$tet$, $tet$Amblypelta no Amorbus maka peste hanesan insetu ne'ebé estraga eukaliptu hodi sona ai-horis nia sanak sira no hemu ai-horis nia been. Iha ai-horis sira ne'ebé sei ki'ik tebes, ida-ne'e bele halo ai-horis nia tutun sira namlaik no mate fali, dala ruma hamate ai-horis nia sanak prinsipál no husik ai-hun ne'e sai hanesan ai-horis ka ai-riin. Opsaun kontrolu naturál sira seidauk estuda ho di'ak, maibé dala ruma sujere atu kuda ai-horis sira seluk hamutuk (interkultivasaun).$tet$),
    ($tet$Parkia speciosa$tet$, $tet$Petai‑cina/Pete/Petai$tet$, $tet$Parkia komemora esploradór Scottish Mungo Park, no speciosa maka lian Latin ba "espontante" ka "furak", refere ba ai-horis nia ai-funan sira ne'ebé furak.$tet$, $tet$Parkia speciosa ladún komún no liuliu hetan hanesan ai-horis uma-laran nian ne'ebé kuda iha aldeia sira ne'ebé iha altitude aas liu, liuliu hale'u Dare, Aileu, no Ermera.$tet$, $tet$Ai-hun ida ne'ebé boot-médiu ho aas besik 15-40 m, ho sanak ki'ik sira ne'ebé dala barak iha fulun uitoan; tahan boot, ho fulun, fulin kompostu duplu ho fulin ki'ik par barak; Ai-funan sira mutin-kreme, ka kinur-mutin, ne'ebé tau metin iha ulun sira ne'ebé forte; Ai-fuan ho pod boot ho naruk besik 35-55 cm, loos ka baibain liu nakdoko, latan iha faskulante ki'ik sira, matak bainhira sei ki'ik no sai metan bainhira tasak, pod ida-idak kaer fini boot besik 10-18; Fini sira boot, no fini sira ne'e bele han no baibain han hanesan ai-horis (koñesidu ho gostu hanesan ai-horis no ho morin ne'ebé maka'as tebes); Espésie sira bele identifika hosi fulin sira ne'ebé iha fulun no pod naruk sira ne'ebé namlele iha ramu ho fini boot sira ne'ebé bele han iha laran.$tet$, $tet$Kompostu pinnadu (Duplu)$tet$, $tet$Pod (fuan naruk ne’ebé iha musan iha laran)$tet$, $tet$Funan: Maiu to'o Juñu; Frutasaun: Agostu to'o Setembru$tet$, $tet$Parkia speciosa (petai/koto iis) fini mai husi pod naruk ne’ebé kontén fini boot oioin. Atu hetan rezultadu di'ak liu, halibur pod ne'ebé tasak ona diretamente husi ai-horis bainhira sira dezenvolve tomak ona atu evita estragu husi insetu no problema fungal, hafoin loke vagem sira hodi hasai fini sira lakleur depois de kolleita. Iha isin sira falun fini ne'ebé toos ne'ebé bele atraza jerminasaun, nune'e kultivadór barak hasai fulun fini nian ka tesi fini besik mikropil hodi ajuda be’e tama no halais moris. Rega fini iha bee laran molok kuda mós ajuda hadi’a uniformidade jerminasaun. Fini sira kuda iha superfísie husi mistura ne'ebé iha drenajen di'ak hanesan rai-henek ka mistura rai-henek-rai no prense uitoan lahó taka kle’an, tanba kontaktu kmaan ho umidade enkoraja moris. Iha kondisaun di'ak, fini sira ne'ebé trata ona normalmente hahú moris iha loron 10-15 nia laran, no jerminasaun uniforme no kreximentu ai-oan nian ne'ebé maka'as tuir ho umidade no naroman ne'ebé adekuadu$tet$, $tet$Parkia speciosa bele hetan estragu husi insetu no fungus ne'ebé estraga ai no halo aat ai, no ai ne'ebé mamar liu fasil liu ba insetu sira atu ataka. Iha área balu, larva moth nian mós bele estraga fini sira. Ai-fuan, ai-funan, musan, no kulit bele han hosi animál no manu sira hanesan manu-fuik, samea, no esquilo. Jestaun inklui mantén ai maran no proteje ho di'ak hafoin tesi, hasai parte sira ne'ebé hetan ataka maka'as sedu, no uza protesaun fíziku simples hanesan lutu ka guarda sira iha ne'ebé estragu hosi animál fuik sira maka komún.$tet$),
    ($tet$Terminalia catappa$tet$, $tet$Ai‑Kalesi/Ketapang/Ai‑lese$tet$, $tet$Terminalia refere ba ai-tahan sira ne'ebé halibur iha "rohan" hosi sanak sira (husi Latin terminalis), no catappa mai hosi naran lokál/komún katappa ne'ebé uza iha parte sira hosi Ázia Súl no Sudeste ba ai-hun ida-ne'e.$tet$, $tet$Terminalia catappa baibain moris iha área tasi-ibun sira.$tet$, $tet$Ai-hun boot ida ne'ebé monu to'o semi-verde, ho korvo ida ne'ebé iha kamada ne'ebé distintu tebes, hanesan págoda; Tahan sira ne'ebé boot tebes, luan, no hanesan kulit, halibur besik iha sanak sira nia rohan, sai kinur ba laranja-mean molok monu; Ai-funan ki'ik, mutin-matak iha grupu ne'ebé mihis hanesan ai-sanak husi ai-funan nia hun, ladún hatudu; Ai-fuan oval to'o modelu hanesan almond nia fuan, latan uitoan no mós, verde bainhira sei ki'ik, sai mean, mean ka kór-roxu bainhira nia tasak, ho Kamada li’ur ne'ebé fibrozu; Fini "fatuk" ida ne'ebé toos iha ai-fuan nia laran ne'ebé iha musan ida ne'ebé bele han (baibain hanaran amêndoa tropikál); Espésie sira bele identifika hosi sanak "pagoda" ne'ebé latan, sanak boot tebes ne'ebé sai mean antes monu, no ai-fuan sira ne'ebé hanesan amêndoa ho musan ne'ebé bele han.$tet$, $tet$Simples$tet$, $tet$Drupe /ai-fuan ne'ebe iha parte toos ida ne'ebe proteje ninia musan$tet$, $tet$Funan: Maiu to'o Juñu; Frutasaun: Abril to'o Juñu$tet$, $tet$Terminalia catappa produz drupe ovoide ne'ebé sai hosi verde ba mean ka mean-kafé bainhira tasak, isin taka fatuk ne'ebé toos fini iha laran. Ai-fuan sira ne'ebé tasak di'ak liu halibur entre fulan-Abril no Juñu, di'ak liu halibur diretamente hosi ai-hun ka halibur fresku hosi rai. Hafoin rekolla, kamada liur ne'ebé iha isin tenke hasai no fase nu sira no maran iha loro-matan. Tanba endokarpu ne'ebé toos atraza jerminasaun, harahun uitoan kulit ka rega ai-fuan durante kalan ida hadi'a tebes rezultadu sira. Fini sira kuda ho kle’an besik 2 cm iha rai-henek ne'ebé iha drenajen di'ak ka rai-henek, di'ak liu tau iha rai-henek. Mantein médiu ne'ebé úmidu maibé labele nakonu ho bee. Jerminasaun normálmente hahú iha semana 3-8 nia laran, lalais liu bainhira kulit rahun. Ai-oan sira moris ho abut ne'ebé maka'as, nune'e rekomenda atu transplanta lalais ba iha kontentór ne'ebé kle’an. Sombra ne'ebé kmaan no rega beibeik suporta kreximentu sedu ne'ebé saudavel.$tet$, $tet$Terminalia catappa normálmente hetan problema ho peste bainhira nia sei ki'ik, liuliu hosi insetu sira ne'ebé han ai-tahan ne'ebé bele hasai ai-tahan barak. Kestaun komún seluk maka insetu ki'ik sira ne'ebé hanaran thrips ne'ebé estraga ai-funan sira, halo sira sai bronze ka sunu, no bele kauza ai-funan monu lalais. Estratéjia di'ak liu maka halo verifikasaun beibeik, hasai peste sira ho liman iha ai-hun ki'ik sira, no tesi no estraga ho seguru ai-funan no musan sira ne'ebé afetadu maka'as.$tet$),
    ($tet$Peltophorum pterocarpum$tet$, $tet$Ai‑silose/Ai‑mame$tet$, $tet$Peltophorum mai hosi lian Gregu peltē ("eskudu ki'ik") + phoros ("lori"), ne'ebé refere ba nia vagem sira ne'ebé hanesan eskudu, no pterocarpum mai hosi lian Gregu pteron ("liras") + karpos ("ai-fuan"), ne'ebé signifika "ai-fuan ho liras".$tet$, $tet$Peltophorum pterocarpum moris iha estrada ninin ne'ebé iha foho.$tet$, $tet$Ai-hun ida ne'ebé buras lalais ho ai-horis ne'ebé sempre verde to'o semi-deciduous médiu-boot, ho koroa redonda ne'ebé luan no sanak sira ne'ebé namkari, kulit kinur-kafé no rahun bainhira nia sai tuan; Tahan boot, ho fulun, ho fulin kompostu duplu ho fulin ki'ik barak ne'ebé fó aparénsia hanesan samake ne'ebé kmaan; Ai-funan sira kór kinur osan-mean nabilan, morin uitoan, moris iha sanak boot sira ne'ebé hamriik loos iha sanak sira nia rohan, dala barak halo koroa tomak sai kinur bainhira buras; Ai-fuan ne'ebé lahan, mihis, ai-tahan, oval to'o oblong, mean-malahuk to'o kafé nakukun bainhira tasak, normálmente la nakloke; Fini 1-4 fini kada pod, toos no kór-kafé; Espésie sira bele identifika hosi ai-funan boot sira ho kór-mean-mean no ai-funan sira ne'ebé latan ho kór-kafé-mean hamutuk ho fulin sira ne'ebé iha fulun.$tet$, $tet$Kompostu pinnadu (Duplu)$tet$, $tet$Pod (fuan naruk ne’ebé iha musan iha laran)$tet$, $tet$Funan: Abril to'o Maiu; Frutasaun: Abril to'o Juñu$tet$, $tet$Peltophorum pterocarpum prodús ai-fuan pod ne'ebé latan no ai-fuan ne'ebé nakfila hosi mean-nakukun ba kór-kafé nakukun ka metan bainhira sai tasak. Kada vagem/pod iha fini 1-4 ne'ebé toos no latan. Ai-fuan ne'ebé tasak ona halibur hosi ai-hun entre fulan-Abril no Juñu, maran to'o sira fahe ho fasil, no fini sira hamoos. Tanba fini sira iha fulun ne'ebé toos tebes, pré-tratamentu maka esensiál: rega iha bee ho temperatura ambiente durante oras 24 ka ba tempu badak iha bee manas hadi'a tebes jerminasaun. Kuda fini sira ho kle’an besik 1 cm iha rai-henek no rai-henek ne'ebé iha drenajen di'ak, taka sira ho kmaan. Jerminasaun normálmente hahú iha semana 1-2 nia laran bainhira hetan tratamentu ho di'ak. Fó mahon ne'ebé kmaan durante kreximentu sedu, hafoin neineik-neineik hasai ai-oan sira ba loro-matan tomak. Mantein rega beibeik lahó bee-sae. Ai-oan sira moris lalais no bele transplanta hafoin semana 4-6 bainhira aas maizumenus 10 cm.$tet$, $tet$Peltophorum pterocarpum normálmente maka'as, no problema barak liu maka insetu sira ne'ebé han ai-tahan dala balu de'it. Bagworms bele haree hosi "saku" ki'ik sira ne'ebé latan iha ai-tahan no ai-sanak sira, no sira neineik-neineik halo mihis kanopi /mahon hodi han ai-sanak sira. Lagarta looper bele hasai ai-funan sira no halo koroa sai mihis ka kuaze laiha ai-tahan durante surtu sira, liuliu iha ai-horis sira ne'ebé sei ki'ik. Estratéjia simples maka atu mantén ai-horis sira metin, verifika sira beibeik, enkoraja manu sira no insetu sira ne'ebé ajuda, no hili ho liman ka tesi no estraga parte sira ne'ebé infestadu maka'as bainhira problema ne'e ki'ik.$tet$),
    ($tet$Santalum album$tet$, $tet$Ai‑kameli$tet$, $tet$Santalum mai hosi liafuan Árabe-Pérsia sandal (sándalu), no album maka Latin ba "mutin", refere ba nia ai-mutin (liuliu ai-sapi).$tet$, $tet$Iha Timor-Leste, Santalum album moris naturalmente iha ai-laran monsaun maran/arbustu, di’ak liu iha rai-henek ka fatuk ne’ebé iha drenajen di’ak$tet$, $tet$Ai-hun ki'ik to'o médiu ne'ebé sempre verde, normálmente ho ai-tahan ne'ebé mihis no koroa ne'ebé arredondadu, kulit malahuk to'o kór-kafé nakukun no nakfera bainhira tuan; ai-fuan nia morin maka'as; Sai simples, kontráriu, mos no kulit, kór verde médiu no nabilan uitoan; Ai-funan ki'ik, iha grupu badak husi junta sanak, to'o verde no krema bainhira sai nurak mean-kafé ka kór-roxu bainhira sira sai tasak, ho morin ne'ebé kmaan; Ai-fuan ho isin-lolon ki'ik ne'ebé redonda to'o oval, kór-verde bainhira sei ki'ik no sai kór-roxu-metan bainhira tasak ona. ai-sándalu nia morin maka'as hosi ai-hun.$tet$, $tet$Simples$tet$, $tet$Drupe /ai-fuan ne'ebe iha parte toos ida ne'ebe proteje ninia musan$tet$, $tet$Funan: Novembru to'o Dezembru; Frutasaun: Marsu to'o Juñu$tet$, $tet$Ai-sándalu /kameli prodús fini ki'ik no toos ne'ebé taka iha ai-fuan kór-roxu-metan ne'ebé maka tasak iha tempu maran. Ai-fuan sira ne'ebé tasak rekolla diretamente hosi ai-hun, hamoos hodi hasai pulpa /isin, no hamaran iha anin molok kuda. Fini sira moris di'ak liu iha meiu ne'ebé iha drenajen di'ak hanesan rai-henek ka rai-henek, ne'ebé mantén úmidu maibé la nakonu ho bee. Jerminasaun normálmente hahú iha semana 2-4 nia laran iha kondisaun manas no mahon. Ai-sándalu maka espésie semi-parazita ida no presiza ai-horis uma-na'in ne'ebé adekuadu hosi faze inísiu atu fornese nutriente sira liuhosi ligasaun haustoriál. Ai-moruk ka ai-horis ne'ebé moris lalais hanesan Alternanthera, Cajanus nst baibain uza hanesan uma-na'in prinsipál. Ai-oan sira tenke kuda iha mahon parsiál, ho rega ho kuidadu, to'o estabelese ho di'ak molok kuda iha to'os ho espésie uma-na'in ba tempu naruk ne'ebé adekuadu.$tet$, $tet$Santalum album bele hetan afetadu maka'as hosi "moras spike", ne'ebé hada'et liuhosi kontaktu ho abut no bele hamate ai-horis sira iha tinan 1-2 nia laran hafoin sintoma sira hahú, no ai-funan sira bele para atu fó fuan. Tanba laiha ai-moruk ida ne'ebé konfiável bainhira ai-hun ida hetan infesaun, estratéjia di'ak liu maka prevensaun: tau espasu ne'ebé di'ak (besik 5–6 m) no evita atu kuda besik liu ba malu. Kuda ai-sándalu ho ai-horis kompañeiru/uma-na'in ne'ebé apropriadu hanesan Casuarina, Acacia, ka Eucalyptus, enkuantu mantein ai-horis uma-na'in saudavel ho du'ut no mahon di'ak ba ai-oan sira. Hamenus mós insetu sira ne'ebé xupa been ne'ebé bele ajuda hada'et moras liuhosi uza rede/protesaun hena simples, liuliu ba ai-horis joven sira.$tet$),
    ($tet$Swietenia macrophylla$tet$, $tet$Ai‑mahony$tet$, $tet$Swietenia hanaran tuir Gerard (von) van Swieten, médiku no botániku olandés-austríaku, no macrophylla mai hosi gregu makros ("boot") + phyllon ("tahan"), ne'ebé refere ba ai-hun nia tahan boot sira.$tet$, $tet$Swietenia macrophylla hanesan ai-horis ida ne'ebé popular, la'ós rai-na'in iha Timor-Leste, ne'ebé kuda barak iha área barak tanba nia ai-lolon ne'ebé folin-boot.$tet$, $tet$Ai-hun boot, ne'ebé buras lalais ho fulin to'o semi-verde, normálmente ho ai-hun ne'ebé aas no loos no koroa redonda ne'ebé luan, kulit kór-malahuk-kafé no sai nakfera no fissuradu bainhira idade; ai-lolon ne'e toos no dura, normálmente kór-mean-malahuk; Tahan sira kompostu (pinnate) no alternadu, ho par oioin sira ne'ebé boot, mamar, nabilan, oval to'o ho forma lansa; Ai-funan ki'ik no kór-verde-mutin to'o krema, moris iha sanak sira ne'ebé namkari (panicles), normalmente iha morin ne'ebé kmaan; Fuan kapsula boot, toos, ai-tahan ne'ebé sai kór-kafé no nakloke ba válvula oioin bainhira tasak; Fini barak, lahan no hanesan surat-tahan ho liras naruk ba dispersaun anin nian; Espésie ne'e bele identifika hosi ai-horis nia fulin boot ho ai-funan ne'ebé nabilan, kapsula ai-tahan boot ne'ebé nakloke, no fini ho liras barak.$tet$, $tet$Kompostu pinnadu (ida de'it)$tet$, $tet$Kapsul$tet$, $tet$Funan: Jullu to'o Setembru; Fuan: Dezembru to'o Fevereiru$tet$, $tet$Halibur fini sira husi ai-mahoni ne'ebé tasak ona (besik tinan 30-40), ideálmente antes tempu udan, no kuda sira lakleur hafoin halibur atu hetan rezultadu di'ak liu. Hafoin maran iha loro-matan, fini sira bele rai metin no bele moris liu fulan neen. Kuda fini sira lahó pré-tratamentu, tau sira iha fatin ne'ebé kle’an (besik 0.5-1 cm) iha mistura viveiru nian ne'ebé iha drenajen di'ak (ezemplu, ai-tahan, ai-rahun /uut, ai-fuan nia kulit ne'ebé rahun) iha naroman ne'ebé filtradu. Jerminasaun normálmente akontese iha semana 2-3 nia laran, no ai-oan sira prontu atu transplanta bainhira sira atinje aas besik 15-20 cm.$tet$, $tet$Peste prinsipál husi ai-mahoni maka ai-mahogany shoot borer (Hypsipyla robusta), ne'ebé nia larva sira tama iha ai-sanak sira ne'ebé mamar no kauza mate. Ida-ne'e hapara ai-hun atu labele moris ho loos, hodi hamosu kreximentu ne'ebé ladún di'ak no forma ida ne'ebé buras, ho tahan oioin. Atake sira normálmente aat liu iha plantasaun monokultura no kondisaun manas no úmidu (besik 25-30°C). Hamenus risku liuhosi kahur espésie sira (interkultivasaun ho ai-lasu sira hanesan Toona Ciliata ka Pterocarpus indicus), hasai musan/larva sira ne'ebé infestadu, no kuda iha altitude sira ne'ebé ki'ik liu 500 m. Prevene abut dodok hodi mantein rai ho drenajen di'ak, evita bee-sa'e, no fó naroman loro-matan ne'ebé sufisiente ba ai-oan sira.$tet$);

DO $$
DECLARE
    bad text;
BEGIN
    SELECT string_agg(s.scientific_name, ', ') INTO bad
    FROM tet_sheet s
    WHERE (SELECT count(*) FROM public.species_en e
           WHERE lower(btrim(e.scientific_name)) = lower(btrim(s.scientific_name))) <> 1;
    IF bad IS NOT NULL THEN
        RAISE EXCEPTION 'Tetum load: these sheet species do not match exactly one species_en row: %', bad;
    END IF;
END $$;

CREATE TABLE IF NOT EXISTS public.species_tet_backup_20261127 (LIKE public.species_tet);
ALTER TABLE public.species_tet_backup_20261127 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.species_tet_backup_20261127 FROM anon, authenticated;
INSERT INTO public.species_tet_backup_20261127
SELECT * FROM public.species_tet
WHERE NOT EXISTS (SELECT 1 FROM public.species_tet_backup_20261127);

CREATE TEMP TABLE tet_load ON COMMIT DROP AS
SELECT e.species_id, e.scientific_name AS en_name, s.*
FROM tet_sheet s
JOIN public.species_en e ON lower(btrim(e.scientific_name)) = lower(btrim(s.scientific_name));

UPDATE public.species_tet t
SET scientific_name = l.en_name,
    common_name = l.common_name,
    etymology = l.etymology,
    habitat = l.habitat,
    identification_character = l.identification_character,
    leaf_type = l.leaf_type,
    fruit_type = l.fruit_type,
    phenology = l.phenology,
    seed_germination = l.seed_germination,
    pest = l.pest
FROM tet_load l
WHERE t.species_id = l.species_id;

INSERT INTO public.species_tet (species_id, scientific_name, common_name, etymology, habitat, identification_character, leaf_type, fruit_type, phenology, seed_germination, pest)
SELECT l.species_id, l.en_name, l.common_name, l.etymology, l.habitat, l.identification_character, l.leaf_type, l.fruit_type, l.phenology, l.seed_germination, l.pest
FROM tet_load l
WHERE NOT EXISTS (SELECT 1 FROM public.species_tet t WHERE t.species_id = l.species_id);

CREATE TEMP TABLE tet_orphans ON COMMIT DROP AS
SELECT t.species_id FROM public.species_tet t
WHERE NOT EXISTS (SELECT 1 FROM public.species_en e WHERE e.species_id = t.species_id);

DELETE FROM public.species_tet t USING tet_orphans o WHERE t.species_id = o.species_id;

LOCK TABLE public.changelog IN EXCLUSIVE MODE;
INSERT INTO public.changelog (version, entity_id, entity_type, operation)
SELECT base.v + row_number() OVER (ORDER BY c.op, c.species_id), c.species_id, 'species', c.op
FROM (SELECT species_id, 'UPDATE' AS op FROM tet_load
      UNION ALL
      SELECT species_id, 'DELETE' AS op FROM tet_orphans) c
CROSS JOIN (SELECT coalesce(max(version), 0) AS v FROM public.changelog) base;

DO $$
DECLARE
    missing int; extra int; dup int; loaded int;
BEGIN
    SELECT count(*) INTO missing FROM public.species_en e
    WHERE NOT EXISTS (SELECT 1 FROM public.species_tet t WHERE t.species_id = e.species_id);
    SELECT count(*) INTO extra FROM public.species_tet t
    WHERE NOT EXISTS (SELECT 1 FROM public.species_en e WHERE e.species_id = t.species_id);
    SELECT count(*) - count(DISTINCT species_id) INTO dup FROM public.species_tet;
    SELECT count(*) INTO loaded FROM public.species_tet t JOIN tet_load l USING (species_id)
    WHERE t.common_name = l.common_name AND t.pest = l.pest AND t.leaf_type = l.leaf_type;
    IF missing <> 0 OR extra <> 0 OR dup <> 0 OR loaded <> (SELECT count(*) FROM tet_load) THEN
        RAISE EXCEPTION 'Tetum load check failed: missing=% extra=% duplicate=% loaded=%', missing, extra, dup, loaded;
    END IF;
    RAISE NOTICE 'Tetum load OK: % species updated, % duplicate Tetum rows removed', loaded,
        (SELECT count(*) FROM tet_orphans);
END $$;

COMMIT;

-- After COMMIT, this should list 22 rows with the new Tetum common names:
SELECT t.species_id, t.scientific_name, t.common_name, t.leaf_type, t.fruit_type
FROM public.species_tet t ORDER BY t.species_id;
